PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zone ?point ?class ?tsid
WHERE {
  ?zone a brick:Zone .
  ?zone brick:hasSubArea ?sub .
  ?point brick:isPointOf ?zone .
  ?point rdf:type ?class .
  OPTIONAL { ?point ref:hasTimeseriesId ?tsid }
}

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?label ?uri
WHERE {
  ?uri rdfs:label ?label .
  FILTER (CONTAINS(?label, "Perimeter"))
}

